import{_ as d,o,c,a3 as a}from"./chunks/framework.DAK02U1-.js";const g=JSON.parse('{"title":"交叉编译","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"交叉编译 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/xclang/guide/cross-compiling"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/xclang/guide/cross-compiling"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/guide/cross-compiling"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/guide/cross-compiling"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/guide/cross-compiling"}]]},"headers":[],"relativePath":"zh/xclang/guide/cross-compiling.md","filePath":"zh/xclang/guide/cross-compiling.md","lastUpdated":1794509097000}'),i={name:"zh/xclang/guide/cross-compiling.md"};function t(s,e,l,n,r,h){return o(),c("div",null,[...e[0]||(e[0]=[a('<h1 id="交叉编译" tabindex="-1">交叉编译 <a class="header-anchor" href="#交叉编译" aria-label="Permalink to &quot;交叉编译&quot;">​</a></h1><p>向 <code>clang</code> 或 <code>clang++</code> 传入 <code>--target=&lt;triple&gt;</code>，即可为其他目标平台编译并链接程序。每个主机压缩包都包含编译器、<code>lld</code>，以及所有内置目标平台的 sysroot、预编译运行时库和配置文件，因此交叉编译不需要外部 sysroot 或包装脚本。</p><h2 id="构建其他目标平台的程序" tabindex="-1">构建其他目标平台的程序 <a class="header-anchor" href="#构建其他目标平台的程序" aria-label="Permalink to &quot;构建其他目标平台的程序&quot;">​</a></h2><p>在<a href="./quick-start">快速开始</a>目录（<code>examples/quickstart</code>）下，为 Windows on Arm 编译 <code>hello.cpp</code>：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=aarch64-w64-mingw32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello-windows-arm64.exe</span></span></code></pre></div><h2 id="目标平台与主机" tabindex="-1">目标平台与主机 <a class="header-anchor" href="#目标平台与主机" aria-label="Permalink to &quot;目标平台与主机&quot;">​</a></h2><p>同一个 <code>--target</code> 参数可用于构建 xclang 支持的十个目标平台：</p><table tabindex="0"><thead><tr><th>目标平台</th><th>其他写法</th><th>C 运行时库</th><th>运行环境</th><th>厂商 SDK</th></tr></thead><tbody><tr><td><code>x86_64-unknown-linux-gnu</code></td><td><code>x86_64-pc-linux-gnu</code></td><td>glibc 2.17</td><td>glibc 2.17 及以上的 Linux</td><td></td></tr><tr><td><code>aarch64-unknown-linux-gnu</code></td><td><code>aarch64-pc-linux-gnu</code>, <code>arm64-unknown-linux-gnu</code>, <code>arm64-pc-linux-gnu</code></td><td>glibc 2.17</td><td>glibc 2.17 及以上的 Linux</td><td></td></tr><tr><td><code>x86_64-w64-mingw32</code></td><td><code>x86_64-w64-windows-gnu</code>, <code>x86_64-pc-windows-gnu</code></td><td>mingw-w64 14.0.0，UCRT</td><td>Windows 10 及以上</td><td></td></tr><tr><td><code>aarch64-w64-mingw32</code></td><td><code>aarch64-w64-windows-gnu</code>, <code>aarch64-pc-windows-gnu</code>, <code>arm64-w64-windows-gnu</code>, <code>arm64-pc-windows-gnu</code></td><td>mingw-w64 14.0.0，UCRT</td><td>Windows 10 及以上</td><td></td></tr><tr><td><code>aarch64-apple-darwin</code></td><td><code>aarch64-apple-macos</code>, <code>aarch64-apple-macosx</code>, <code>arm64-apple-darwin</code>, <code>arm64-apple-macos</code>, <code>arm64-apple-macosx</code></td><td>SDK 的 libSystem</td><td>macOS 13.0 及以上</td><td>Apple 的，在 Linux 与 Windows 主机上</td></tr><tr><td><code>x86_64-apple-darwin</code></td><td><code>x86_64-apple-macos</code>, <code>x86_64-apple-macosx</code></td><td>SDK 的 libSystem</td><td>macOS 13.0 及以上</td><td>Apple 的，在 Linux 与 Windows 主机上</td></tr><tr><td><code>x86_64-unknown-linux-musl</code></td><td><code>x86_64-pc-linux-musl</code></td><td>musl 1.2.6，静态链接</td><td>任意 Linux</td><td></td></tr><tr><td><code>aarch64-unknown-linux-musl</code></td><td><code>aarch64-pc-linux-musl</code>, <code>arm64-unknown-linux-musl</code>, <code>arm64-pc-linux-musl</code></td><td>musl 1.2.6，静态链接</td><td>任意 Linux</td><td></td></tr><tr><td><code>x86_64-pc-windows-msvc</code></td><td><code>x86_64-unknown-windows-msvc</code></td><td>微软的 CRT 与 UCRT</td><td>Windows 10 及以上</td><td>微软的</td></tr><tr><td><code>aarch64-pc-windows-msvc</code></td><td><code>aarch64-unknown-windows-msvc</code>, <code>arm64-pc-windows-msvc</code>, <code>arm64-unknown-windows-msvc</code></td><td>微软的 CRT 与 UCRT</td><td>Windows 10 及以上</td><td>微软的</td></tr></tbody></table><p>每个目标平台默认都会静态链接 xclang 的 <code>libc++</code> 与 <code>compiler-rt</code>，并使用 <code>lld</code> 作为链接器（<code>ld.lld</code>、<code>lld-link</code> 或 <code>ld64.lld</code>）。编译出的程序在运行时只依赖所属目标平台系列的操作系统库（<a href="./../design/hermeticity">封闭性</a>）。</p><p>上述十个目标平台均为 <strong>Tier 1</strong>：每次发布都会构建，并在原生的 GitHub 托管 runner 上直接运行测试，不使用模拟器（Tier 2 在模拟器或虚拟化环境下运行测试；Tier 3 仅编译并链接，不实际运行）。其他目标平台见<a href="./../design/roadmap#targets">路线图</a>。各目标平台的 sanitizer 支持情况见 <a href="./../features/sanitizers">sanitizer</a>。</p><p>主机（host）是运行工具链的机器。每个主机平台都有各自的压缩包（<a href="./../reference/releases#assets">版本发布</a>），且每个压缩包都包含上述所有目标平台：</p><table tabindex="0"><thead><tr><th>主机</th><th>压缩包构建环境</th><th>测试环境</th><th>工具链对主机的要求</th></tr></thead><tbody><tr><td><code>x86_64-unknown-linux-gnu</code></td><td>Linux x64</td><td><code>ubuntu-24.04</code></td><td>glibc 2.17 及以上</td></tr><tr><td><code>aarch64-unknown-linux-gnu</code></td><td>Linux x64，交叉编译</td><td><code>ubuntu-24.04-arm</code></td><td>glibc 2.17 及以上</td></tr><tr><td><code>x86_64-w64-mingw32</code></td><td>Linux x64，交叉编译（MinGW 程序）</td><td><code>windows-2025</code></td><td>Windows 10 及以上</td></tr><tr><td><code>aarch64-w64-mingw32</code></td><td>Linux x64，交叉编译（MinGW 程序）</td><td><code>windows-11-arm</code></td><td>Windows 10 及以上</td></tr><tr><td><code>aarch64-apple-darwin</code></td><td>macOS arm64</td><td><code>macos-15</code></td><td>macOS 13 及以上；编译 macOS 目标平台需安装 Xcode 或 Command Line Tools</td></tr><tr><td><code>x86_64-apple-darwin</code></td><td>macOS arm64，交叉编译</td><td><code>macos-15-intel</code></td><td>macOS 13 及以上；编译 macOS 目标平台需安装 Xcode 或 Command Line Tools</td></tr></tbody></table><h2 id="clang-如何查找目标平台文件" tabindex="-1">Clang 如何查找目标平台文件 <a class="header-anchor" href="#clang-如何查找目标平台文件" aria-label="Permalink to &quot;Clang 如何查找目标平台文件&quot;">​</a></h2><p>针对每个 <code>--target</code>，<code>clang</code> 会读取 <code>bin/&lt;triple&gt;.cfg</code>（<code>clang-cl</code> 则读取 <code>bin/&lt;triple&gt;-clang-cl.cfg</code>），并为目标平台的其他写法保留了副本（<a href="./../design/toolchain">工具链结构</a>）。配置文件中的 <code>&lt;CFGDIR&gt;</code> 会展开为 <code>bin/</code>，从而将 <code>clang</code> 指向目标平台的 sysroot 或 SDK、<code>libc++</code> 头文件、<code>compiler-rt</code>、<code>libunwind</code> 和 <code>lld</code>（<a href="./../reference/layout">压缩包目录结构</a>）。</p><p>配置文件同样作用于本机编译，因此在 Linux 上运行 <code>clang++ hello.cpp</code> 时，编译使用的是内置的 glibc 2.17 sysroot，而非主机的 <code>/usr/include</code> 与 <code>/usr/lib</code>。面向 GCC 编写的构建脚本（<code>-latomic</code>、<code>-lgcc</code>、<code>-lgcc_s</code>、<code>-lgcc_eh</code>、<code>-lstdc++</code>）无需修改即可链接（<a href="./../design/hermeticity#gcc-library-names">GCC 库名兼容</a>）。传入 <code>--no-default-config</code> 可跳过目标平台配置文件，使 <code>clang</code> 按上游原版行为查找系统的头文件、运行时库和链接器。</p><h2 id="厂商-sdk" tabindex="-1">厂商 SDK <a class="header-anchor" href="#厂商-sdk" aria-label="Permalink to &quot;厂商 SDK&quot;">​</a></h2><p>有两类目标平台在编译时需要使用 xclang 无法二次分发的厂商 SDK：</p><ul><li><strong><a href="#macos">macOS 目标平台</a></strong>：在 macOS 主机上，<code>clang</code> 直接使用 Xcode 或 Command Line Tools 的 SDK。在 Linux 与 Windows 主机上，先运行一次 <code>xclang sdk fetch macos --accept-license</code> 从 Apple 下载 macOS SDK。</li><li><strong><a href="#msvc-targets">Windows MSVC 目标平台</a></strong>：在任意主机上，先运行一次 <code>xclang sdk fetch windows --accept-license</code> 获取微软的 CRT、STL 与 Windows SDK。在未下载 SDK 的 Windows 主机上，<code>clang</code> 会使用本机安装的 Visual Studio。</li></ul><p><code>xclang sdk fetch</code> 会将各 SDK 解压到 <code>&lt;toolchain&gt;/sdk/</code> 下，并把 <code>&lt;toolchain&gt;/sdk/macos</code> 或 <code>&lt;toolchain&gt;/sdk/windows</code> 指向当前启用的 SDK；这样即使切换 SDK 版本，目标平台配置文件引用的路径也保持不变（<a href="./../reference/xclang-command"><code>xclang</code> 命令</a>）。在 Bazel 中，可在 <code>MODULE.bazel</code> 里声明接受许可证，由仓库规则将 SDK 解压为外部仓库（<a href="./../integrations/bazel#build-for-msvc-and-for-macos-anywhere">Bazel</a>）。</p><p>Apple 的 SDK 协议与微软的 Visual Studio 许可证只允许使用，不允许二次分发。未传入 <code>--accept-license</code> 时，<code>xclang sdk fetch</code> 会打印厂商的许可条款；传入后会依据 <code>xclang/sdk-versions.json</code> 中锁定的安装包 URL、文件大小、<code>sha256</code> 摘要和 SDK 内容摘要，直接从 Apple 与微软的服务器下载与 GitHub runner 镜像（<code>macos-latest</code>、<code>windows-2025</code>、<code>windows-2022</code>）一致的版本。Apple 的条款仅允许在 Apple 硬件上使用 macOS SDK；是否依据这些条款在 Linux 或 Windows 上用它构建 macOS 程序，由用户自行决定。</p><h2 id="平台的-c-标准库" tabindex="-1">平台的 C++ 标准库 <a class="header-anchor" href="#平台的-c-标准库" aria-label="Permalink to &quot;平台的 C++ 标准库&quot;">​</a></h2><p>如果程序需要跨接口向使用平台的 C++ 标准库编译的库（例如 Linux 发行版自带的 Qt、Boost，或用 MSVC 编译的 Windows 库）传递 C++ 类型，就必须使用同一个 C++ 标准库。此时需向所有编译和链接命令（包括 C 源文件）传入 <code>-stdlib=platform</code>（或 <code>-stdlib=libstdc++</code>；在 <code>clang-cl</code> 中为 <code>/clang:-stdlib=platform</code>）：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -stdlib=platform</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -stdlib=platform</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=x86_64-pc-windows-msvc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.exe</span></span></code></pre></div><p>这个参数会选用 <code>bin/&lt;triple&gt;-system.cfg</code>（或 <code>&lt;triple&gt;-clang-cl-system.cfg</code>，由<a href="./../reference/patches">补丁 0018</a> 支持），保留 <code>lld</code>、部署目标版本与 C 运行时库设置，同时去掉 xclang 的 <code>libc++</code> 和内置 sysroot：</p><table tabindex="0"><thead><tr><th>目标平台</th><th>C++ 标准库</th><th>sysroot 或 SDK</th><th>运行时加载项</th></tr></thead><tbody><tr><td>Linux（glibc）</td><td>GCC 的共享库版 <code>libstdc++</code></td><td>主机环境、发行版的交叉编译包（<code>g++-aarch64-linux-gnu</code>）或 <code>--sysroot</code></td><td>系统的 <code>libstdc++.so.6</code>、<code>libgcc_s.so.1</code>，以及构建环境的 glibc（而非 2.17）</td></tr><tr><td>Linux（musl）</td><td>sysroot 中的 <code>libstdc++</code></td><td><code>--sysroot</code>（例如 Alpine 根目录）</td><td>由所用的 sysroot 决定</td></tr><tr><td>Windows（MinGW）</td><td>sysroot 中的 <code>libstdc++</code></td><td><code>--sysroot</code>（例如 MSYS2 的 <code>ucrt64</code>，或链接了发行版 <code>mingw-w64</code> 的目录）</td><td>由所用的 sysroot 决定</td></tr><tr><td>Windows（MSVC）</td><td>微软的 STL</td><td>下载的 Windows SDK，或 Windows 本机的 Visual Studio</td><td>无新增依赖：STL 配合混合 CRT 静态链接</td></tr><tr><td>macOS</td><td>SDK 中的 <code>libc++</code></td><td>Xcode 的 SDK，或通过 <code>xclang sdk fetch macos</code> 下载的 SDK</td><td>操作系统的 <code>/usr/lib/libc++.1.dylib</code></td></tr></tbody></table><p>在 Debian 或 Ubuntu 上使用 MinGW 时，请将 <code>--sysroot</code> 指向一个包含两个符号链接的目录：把 <code>x86_64-w64-mingw32</code> 指向 <code>/usr/x86_64-w64-mingw32</code>，把 <code>lib/gcc</code> 指向 <code>/usr/lib/gcc</code>（若直接传入 <code>--sysroot=/usr</code>，则会引入 Linux 主机自身的 <code>/usr/include</code> 与 <code>/usr/lib</code>）。</p><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h2><h3 id="glibc-2-17-基线、-static-pie-与-pg" tabindex="-1">glibc 2.17 基线、<code>-static-pie</code> 与 <code>-pg</code> <a class="header-anchor" href="#glibc-2-17-基线、-static-pie-与-pg" aria-label="Permalink to &quot;glibc 2.17 基线、`-static-pie` 与 `-pg`&quot;">​</a></h3><p><code>x86_64-unknown-linux-gnu</code> 与 <code>aarch64-unknown-linux-gnu</code> 基于 <code>&lt;toolchain&gt;/&lt;triple&gt;/</code> 下内置的 glibc 2.17 sysroot 编译并链接，2.17 即生成产物运行时所需的最低 glibc 版本（<a href="./../design/hermeticity#why-glibc-2-17">为什么选择 glibc 2.17</a>；更高版本的 glibc 目标平台目前在<a href="./../design/roadmap#glibc-newer">考虑中</a>）。</p><ul><li><strong>不支持 <code>-static-pie</code></strong>：glibc 2.17 没有 <code>rcrt1.o</code>。如需静态链接 glibc 程序请使用 <code>-static</code>，或改用支持 <code>-static-pie</code> 的 <a href="#musl-targets">musl 目标平台</a>。</li><li><strong><code>-pg</code> 需要配合 <code>-no-pie</code></strong>：glibc 2.17 的 <code>gcrt1.o</code> 未编译为位置无关代码（PIC）。</li><li><strong>不含 <code>quadmath.h</code></strong>：<code>libquadmath</code> 是 GCC 的库；不过 <code>__float128</code> 运算本身可通过 <code>clang</code> 与 <code>compiler-rt</code> 正常使用。</li><li><strong><code>-nodefaultlibs</code> 与 <code>libunwind</code></strong>：由于 sysroot 中的 <code>libgcc_s.a</code> 是空静态库，像 <code>rustc</code> 编译 <code>*-unknown-linux-gnu</code> 那样使用 <code>-nodefaultlibs</code> 链接时不会提供栈展开库（unwinder）。构建 Rust 项目请使用 <code>xclang cargo</code>，或手动传入 <code>-Clink-arg=-l:libunwind.a</code>（<a href="./../integrations/cargo">Rust 与 Cargo</a>）。</li></ul><h3 id="musl-目标平台" tabindex="-1">musl 目标平台 <a class="header-anchor" href="#musl-目标平台" aria-label="Permalink to &quot;musl 目标平台&quot;">​</a></h3><p><code>x86_64-unknown-linux-musl</code> 与 <code>aarch64-unknown-linux-musl</code> 会将 musl 1.2.6（含上游安全补丁、供 C 回调使用的栈展开表以及 Linux 6.18 UAPI 头文件）及所有运行时库静态链接进可执行文件：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=x86_64-unknown-linux-musl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello-static-x64</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=aarch64-unknown-linux-musl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello-static-arm64</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llvm-readelf</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --program-headers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello-static-x64</span></span></code></pre></div><p>生成的二进制文件不含 <code>INTERP</code> 程序头与动态段（dynamic section），直接向 Linux 内核发起系统调用，可在同架构的任意 Linux 上运行。</p><ul><li><strong>默认 <code>-static</code>，可按需启用 <code>-static-pie</code></strong>：配置文件默认传入 <code>-static</code> 并生成 <code>ET_EXEC</code> 二进制文件，从而不会拒绝 CMake 或 <code>rustc</code> 传入的 <code>-no-pie</code>。在命令行传入 <code>-static-pie</code> 即可使用 <code>rcrt1.o</code> 构建支持 ASLR 的位置无关静态二进制文件。</li><li><strong>不支持共享库</strong>：sysroot 使用 <code>--disable-shared</code> 构建，不包含 <code>libc.so</code>。内置 sysroot 不支持动态链接 musl、调用 <code>dlopen</code> 或构建 <code>-shared</code> 共享库（如需构建动态链接的 musl 程序，请配合 <code>--sysroot</code> 使用 <a href="#the-platform-s-c-library"><code>-stdlib=platform</code></a>）。</li></ul><p>musl 与 glibc 在运行时行为上的差异如下（性能数据测自 4 核 GitHub Linux x64 runner）：</p><ul><li><strong>多线程下的 <code>malloc</code></strong>：musl 的内存分配器使用一把多线程争用的锁。单线程执行 400 万次 16 至 528 字节的 <code>malloc</code> 与 <code>free</code> 耗时 0.21 s（glibc 为 0.07 s），4 个线程同时执行则耗时 4.8 s（glibc 为 0.12 s）。若程序在多线程下频繁分配内存，建议链接自定义的内存分配器。</li><li><strong>区域设置（locale）</strong>：musl 不包含区域设置数据，始终按 <code>C</code> locale 格式化：在 <code>en_US.UTF-8</code> 下，<code>printf(&quot;%&#39;.1f&quot;, 1234567.5)</code> 会输出 <code>1234567.5</code>（glibc 则输出 <code>1,234,567.5</code>），<code>libc++</code> 的 <code>std::locale</code> 表现相同。</li><li><strong>名称解析</strong>：musl 直接读取 <code>/etc/hosts</code> 与 <code>/etc/resolv.conf</code> 并发起 DNS 查询，不使用 NSS（<code>nsswitch.conf</code> 模块），因此无法解析 mDNS 的 <code>.local</code> 域名以及 LDAP 或 SSSD 的用户和组。</li></ul><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><p>MinGW 与 MSVC 目标平台均使用 Windows 10 及更高版本自带的 UCRT（<a href="./../design/windows">Windows 设计</a>）。</p><h3 id="mingw-目标平台" tabindex="-1">MinGW 目标平台 <a class="header-anchor" href="#mingw-目标平台" aria-label="Permalink to &quot;MinGW 目标平台&quot;">​</a></h3><p><code>x86_64-w64-mingw32</code> 与 <code>aarch64-w64-mingw32</code> 随每个工具链压缩包内置，并使用 <code>ld.lld</code> 静态链接 <code>libc++</code>、<code>libc++abi</code>、<code>libunwind</code>、<code>winpthreads</code> 和 <code>compiler-rt</code>。</p><ul><li><strong><code>.exe</code> 输出文件名</strong>：在所有主机上，当输出文件名不带扩展名时，MinGW 链接都会自动补上 <code>.exe</code>（<code>-o hello</code> 会生成 <code>hello.exe</code>）。</li><li><strong>头文件与 <code>--gc-sections</code></strong>：MinGW-w64 的头文件名均为小写（<code>windows.h</code>、<code>basetsd.h</code>、<code>winsock2.h</code>）；请使用小写的 <code>#include</code> 名称以确保在区分大小写的文件系统上正常编译，并在依赖未引用的 COMDAT 初始化器注册测试时避免传入 <code>-Wl,--gc-sections</code>（<a href="./../design/windows#gc-sections-and-static-initializers"><code>gc-sections</code> 与静态初始化器</a>）。</li><li><strong>Rust 的 <code>-gnullvm</code> 目标平台</strong>：请使用 <code>x86_64-pc-windows-gnullvm</code> 与 <code>aarch64-pc-windows-gnullvm</code>，而非 <code>*-pc-windows-gnu</code>。<code>-gnullvm</code> 目标平台会链接 <code>libunwind</code> 与 UCRT，与 xclang 的 MinGW sysroot 保持一致（<a href="./../integrations/cargo">Rust 与 Cargo</a>）。</li></ul><h3 id="msvc-目标平台" tabindex="-1">MSVC 目标平台 <a class="header-anchor" href="#msvc-目标平台" aria-label="Permalink to &quot;MSVC 目标平台&quot;">​</a></h3><p><code>x86_64-pc-windows-msvc</code> 与 <code>aarch64-pc-windows-msvc</code> 面向 MSVC ABI 构建；链接由 MSVC 编译的库、重度使用 COM 的代码或 Windows 厂商 SDK 时均需要 MSVC ABI。先运行一次命令获取微软的 CRT、STL 与 Windows SDK，即可在任意主机上使用 <code>clang++</code> 或 <code>clang-cl</code> 构建：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xclang</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> windows</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --accept-license</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=x86_64-pc-windows-msvc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello-msvc-x64.exe</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clang-cl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /O2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /EHsc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Fehello-cl.exe</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clang-cl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /O2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /EHsc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=aarch64-pc-windows-msvc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Fehello-cl-arm64.exe</span></span></code></pre></div><ul><li><p><strong>选择 SDK 版本</strong>：<code>xclang sdk fetch windows</code> 默认下载 <code>windows-latest</code> 预设（<code>windows-2025-vs2026</code>：MSVC 14.51 与 Windows SDK 10.0.26100）。传入 <code>--preset windows-2022</code> 可选择 MSVC 14.44，也可手动传入 <code>--msvc-version</code>、<code>--sdk-version</code> 与 <code>--arch x86_64,aarch64,x86</code>。运行 <code>xclang sdk use &lt;name&gt;</code> 可切换当前启用的 SDK（<a href="./../reference/xclang-command"><code>xclang</code> 命令</a>）。在未下载 SDK（或传入了 <code>--no-default-config</code>）的 Windows 主机上，<code>clang</code> 会使用本机安装的 Visual Studio；在未下载 SDK 的 Linux 与 macOS 主机上，编译包含 CRT 头文件的文件会立即报错停止（<code>-ffreestanding</code> 则无需 SDK 即可工作）。</p></li><li><p><strong><code>clang-cl</code></strong>：直接运行 <code>clang-cl</code> 时会读取 <code>&lt;host-triple&gt;-clang-cl.cfg</code>，无需传入 <code>--target</code> 即可构建当前主机架构的 MSVC 目标平台。在 macOS 上，<code>clang-cl</code> 会将形如 <code>/Users/me/hello.cpp</code> 的输入路径当作 <code>/U</code> 选项解析：请把输入文件放在 <code>--</code> 之后，或使用 <code>/Tp</code> 显式指定。在 <a href="./../integrations/cmake">CMake</a> 与 <a href="./../integrations/bazel">Bazel</a> 中，xclang 使用 GNU 风格的 <code>clang++</code> 驱动而非 <code>clang-cl</code>。</p></li><li><p><strong>C 运行时库选择</strong>：默认情况下，二进制文件会静态链接 <code>libc++</code>（或微软的 STL）以及 VC 运行时库（<code>libvcruntime.lib</code>、<code>libcmt.lib</code>），并将 UCRT 动态链接到 <code>ucrtbase.dll</code>（即混合 CRT；见 <a href="./../design/windows#the-hybrid-crt">Windows 设计</a>）。如需选择其他 C 运行时库：</p><table tabindex="0"><thead><tr><th>C 运行时库</th><th><code>clang</code>、<code>clang++</code></th><th><code>clang-cl</code></th></tr></thead><tbody><tr><td>混合 CRT（默认）</td><td>（默认）</td><td><code>/MT</code>（默认）</td></tr><tr><td>DLL 运行时（<code>vcruntime140.dll</code>，使用 STL 时还包括 <code>msvcp140.dll</code>）</td><td><code>-fms-runtime-lib=dll</code></td><td><code>/MD</code></td></tr><tr><td>全部静态链接（含 UCRT）</td><td><code>-Wl,/nodefaultlib:ucrt.lib -llibucrt</code></td><td><code>/link /nodefaultlib:ucrt.lib libucrt.lib</code></td></tr><tr><td>静态调试版 CRT</td><td><code>-fms-runtime-lib=static_dbg -Wl,/nodefaultlib:ucrt.lib</code></td><td><code>/MTd /link /nodefaultlib:ucrt.lib</code></td></tr></tbody></table><p><code>/MDd</code> 会加载仅由 Visual Studio 安装提供的 <code>ucrtbased.dll</code>。</p></li><li><p><strong>C++ 标准版本</strong>：与 <code>cl.exe</code> 一样，<code>clang</code> 在 MSVC 目标平台上默认采用 C++14 标准。微软的 STL 在 C++14 模式下也暴露了 <code>std::is_integral_v</code> 等部分 C++17 标准库模板，而 <code>libc++</code> 仅从 C++17 起提供它们；如果代码依赖这些模板，请传入 <code>-std=c++17</code>（<code>/std:c++17</code>）或更高标准。</p></li></ul><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><p>macOS 目标平台 <code>aarch64-apple-darwin</code> 与 <code>x86_64-apple-darwin</code> 基于 Apple 的 macOS SDK 编译，并使用 <code>ld64.lld</code> 静态链接 xclang 的 <code>libc++</code> 与 <code>libc++abi</code>（<a href="./../design/macos">macOS 设计</a>）。</p><h3 id="在-macos-主机上" tabindex="-1">在 macOS 主机上 <a class="header-anchor" href="#在-macos-主机上" aria-label="Permalink to &quot;在 macOS 主机上&quot;">​</a></h3><p>在 macOS 主机上，<code>clang</code> 直接使用本机 Xcode 或 Command Line Tools 的 SDK，无需通过 <code>xclang</code> 下载任何文件：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=aarch64-apple-darwin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello-macos-arm64</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=x86_64-apple-darwin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello-macos-x64</span></span></code></pre></div><h3 id="在-linux-与-windows-主机上" tabindex="-1">在 Linux 与 Windows 主机上 <a class="header-anchor" href="#在-linux-与-windows-主机上" aria-label="Permalink to &quot;在 Linux 与 Windows 主机上&quot;">​</a></h3><p>在 Linux 与 Windows 主机上，先运行一次 <code>xclang sdk fetch macos --accept-license</code> 获取 Apple 的 macOS SDK，即可通过 <code>--target</code> 为任一 macOS 架构构建程序：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xclang</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sdk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> macos</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --accept-license</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=arm64-apple-macos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello-macos-arm64</span></span></code></pre></div><table tabindex="0"><thead><tr><th>主机</th><th>使用的 SDK</th></tr></thead><tbody><tr><td>macOS</td><td>最后一个 <code>-isysroot</code>，否则为 <code>SDKROOT</code>，再否则为 Xcode 的 SDK（<code>xcselect</code>）</td></tr><tr><td>Linux、Windows</td><td>命令行上最后一个 <code>-isysroot</code>，否则为 <code>&lt;toolchain&gt;/sdk/macos</code></td></tr></tbody></table><p>在 Linux 与 Windows 主机上，目标平台配置文件的开头是 <code>-isysroot &lt;CFGDIR&gt;/../sdk/macos</code>。由于只有未传入 <code>-isysroot</code> 参数时 <code>clang</code> 才会读取 <code>SDKROOT</code>，且 <code>--sysroot</code> 仅作用于链接步骤，如需指定其他 SDK，请在命令行传入 <code>-isysroot &lt;dir&gt;</code>（Cargo、<code>rustc</code> 以及 xclang 的 <a href="./../integrations/cmake">CMake</a> 包会将 <code>SDKROOT</code> 转换为 <code>-isysroot</code> 传入）。</p><h3 id="预设与版本" tabindex="-1">预设与版本 <a class="header-anchor" href="#预设与版本" aria-label="Permalink to &quot;预设与版本&quot;">​</a></h3><ul><li><strong>预设（Preset）</strong>：<code>xclang sdk fetch macos</code> 默认使用 <code>macos-latest</code> 预设（<code>macOS-26-arm64</code>，SDK 26.5）。传入 <code>--preset macos-15</code>（或 <code>macOS-26</code>、<code>macOS-15-arm64</code>）可匹配对应的 GitHub Actions runner 镜像。</li><li><strong>锁定版本</strong>：传入 <code>--version &lt;ver&gt;</code>（如 <code>--version 15</code> 或 <code>--version 15.5</code>）会选取 <code>xclang/sdk-versions.json</code> 中锁定的最新匹配 SDK；运行 <code>xclang sdk use &lt;name&gt;</code> 可在已下载的版本之间切换 <code>&lt;toolchain&gt;/sdk/macos</code>（<a href="./../reference/xclang-command"><code>xclang</code> 命令</a>）。</li><li><strong><code>--version latest</code></strong>：直接查询 Apple 的实时软件更新目录，获取命令运行当下最新可用的 SDK；它没有锁定摘要，也不具备可复现性。</li><li><strong>下架的安装包</strong>：当 Apple 从 CDN 下架某个 Command Line Tools 安装包并替换为重新签名的安装包时，<code>xclang sdk fetch</code> 会回退查询 Apple 的更新目录，并通过解压后 SDK 的内容摘要校验其完整性（<a href="./../design/macos#packages-apple-withdraws-and-content-digests">macOS 设计</a>）。</li></ul><h3 id="stdlib-platform-与部署目标版本" tabindex="-1"><code>-stdlib=platform</code> 与部署目标版本 <a class="header-anchor" href="#stdlib-platform-与部署目标版本" aria-label="Permalink to &quot;`-stdlib=platform` 与部署目标版本&quot;">​</a></h3><p>目标平台配置文件默认设置 <code>-mmacos-version-min=13.0</code>；可在命令行传入更高版本的 <code>-mmacos-version-min=&lt;ver&gt;</code> 覆盖它。使用 xclang 默认的静态 <code>libc++</code> 时，可用的标准库特性只取决于 xclang 版本，而不受目标 macOS 版本限制。启用 <code>-stdlib=platform</code>（链接操作系统的 <code>/usr/lib/libc++.1.dylib</code>）后，较新的 C++ 标准库符号需要匹配的部署目标版本：例如对浮点数调用 <code>std::format</code> 需要 <code>-mmacos-version-min=13.3</code> 及以上。</p><h3 id="ld64-lld-与-fuse-ld-ld" tabindex="-1"><code>ld64.lld</code> 与 <code>-fuse-ld=ld</code> <a class="header-anchor" href="#ld64-lld-与-fuse-ld-ld" aria-label="Permalink to &quot;`ld64.lld` 与 `-fuse-ld=ld`&quot;">​</a></h3><p>在所有主机上，macOS 目标平台均使用 <code>ld64.lld</code> 链接。<code>ld64.lld</code> 会对 <code>arm64</code> 二进制文件作临时签名（ad-hoc signing），无需调用 <code>codesign</code> 即可在 Apple silicon 上直接运行；<code>llvm-install-name-tool</code> 在修改二进制文件后也会重新签名。使用 Developer ID 证书签名及公证（notarization）需要 Apple 官方工具，编译 <code>.nib</code>、<code>.xib</code> 或资源目录（asset catalog）则需要 macOS 上的 <code>actool</code> 与 <code>ibtool</code>。</p><p>在 macOS 主机上，如需改用 Apple 的 <code>ld</code> 链接非 LTO 目标文件，可传入 <code>-fuse-ld=ld</code>。由于 xclang 不随附 <code>libLTO.dylib</code>，LTO 构建始终使用 <code>ld64.lld</code> 链接。</p><h3 id="两种架构" tabindex="-1">两种架构 <a class="header-anchor" href="#两种架构" aria-label="Permalink to &quot;两种架构&quot;">​</a></h3><p>每个主机压缩包都同时包含 <code>aarch64-apple-darwin</code> 与 <code>x86_64-apple-darwin</code>，可通过 <code>llvm-lipo</code> 将两种架构的程序合并为通用二进制文件（universal binary）。在 macOS 主机上使用 CMake 时，构建另一个 macOS 架构会设置 <code>CMAKE_OSX_ARCHITECTURES</code>，不视为交叉编译（<a href="./../integrations/cmake">CMake</a>）。</p><h2 id="运行构建出的程序" tabindex="-1">运行构建出的程序 <a class="header-anchor" href="#运行构建出的程序" aria-label="Permalink to &quot;运行构建出的程序&quot;">​</a></h2><p>使用 <code>llvm-readobj</code> 查看交叉编译产物的格式与架构：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llvm-readobj</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --file-headers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello-windows-arm64.exe</span></span></code></pre></div><p>输出的头部信息中包含 <code>Format: COFF-ARM64</code> 与 <code>Arch: aarch64</code>。将产物拷贝到对应目标平台的机器上即可直接运行，无需安装任何运行时软件包。部分主机还能直接运行同一操作系统下其他架构的程序：</p><ul><li><code>arm64</code> macOS 可通过 Rosetta 运行 <code>x86_64</code> macOS 程序。</li><li>Windows on Arm 可通过模拟运行 <code>x86_64</code> Windows 程序。</li></ul><p>在一台 runner 上构建并在目标平台的 runner 上运行测试的做法见 <a href="./../integrations/ci#build-on-one-runner-run-on-another">CI</a>。</p><h2 id="在构建系统中使用" tabindex="-1">在构建系统中使用 <a class="header-anchor" href="#在构建系统中使用" aria-label="Permalink to &quot;在构建系统中使用&quot;">​</a></h2><ul><li><a href="./../integrations/cmake">CMake</a>：传入工具链文件并指定 <code>-DXCLANG_TARGET=&lt;target&gt;</code>。</li><li><a href="./../integrations/bazel">Bazel</a>：传入 <code>--platforms=@xclang//platforms:&lt;target&gt;</code>。</li><li><a href="./../integrations/clang">直接使用 clang、Make 与 Meson</a>：向编译器传入 <code>--target=&lt;target&gt;</code>，或将其写入 Meson 交叉编译文件（cross file）。</li><li><a href="./../integrations/cargo">Rust 与 Cargo</a>：运行 <code>xclang cargo build --target &lt;rust-target&gt;</code>。</li></ul><h2 id="构建工具的最低版本要求" tabindex="-1">构建工具的最低版本要求 <a class="header-anchor" href="#构建工具的最低版本要求" aria-label="Permalink to &quot;构建工具的最低版本要求&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>最低版本或目标平台</th><th>原因</th></tr></thead><tbody><tr><td>CMake</td><td>3.28 及以上</td><td>首个无需实验性开关即可构建 C++20 模块的版本；<code>find_package(xclang)</code> 会拒绝更早的版本（<a href="./../integrations/cmake">CMake</a>）</td></tr><tr><td>Ninja</td><td>1.11 及以上</td><td>CMake 构建 C++20 模块所需；目前只有 Ninja 生成器支持为这些目标平台构建模块</td></tr><tr><td>Bazel</td><td>9，搭配 <code>rules_cc</code> 0.2.25 及以上</td><td>工具链基于 <code>rules_cc</code> 0.2.28 的 unix 配置构建（<a href="./../design/bazel-module">Bazel 模块</a>）；使用 C++20 模块需传入 <code>--experimental_cpp_modules</code></td></tr><tr><td>Rust</td><td>MinGW 使用 <code>*-pc-windows-gnullvm</code>（而非 <code>*-windows-gnu</code>）；配合 Windows SDK 时使用 <code>*-pc-windows-msvc</code></td><td><code>*-windows-gnullvm</code> 的标准库链接 <code>libunwind</code> 与 UCRT，与 xclang 的 MinGW sysroot 一致（<a href="./../integrations/cargo">Rust 与 Cargo</a>）</td></tr></tbody></table>',75)])])}const k=d(i,[["render",t]]);export{g as __pageData,k as default};
